"""Public-training-derived codebook with a reversible nonterminal escape."""
import hashlib,json,random,codecs
from collections import Counter
from vs import corpus,ivtff,refcorpus,judge

BOOKS=('it_dante','es_buenamor','en_paston','medieval_czech_01473c19')
SIZES=(500,2000,5000);SEEDS=(17,37,73);TRAIN=50000;TEST=25000;ESC='z'
GALLOWS={'k','t','p','f','ckh','cth','cph','cfh'}

def words(pages):
 return [w for p in pages for l in p.lines if l.unit=='P' for w in l.words if not ivtff.uncertain(w)
         and w.isascii() and w.isalpha() and w.islower()]

def shape(words):
 s=[ivtff.segment(w) for w in words];n=len(words)
 return {'tokens':n,'types':len(set(words)),
   'repeated_non_e':sum(any(g!='e' and v>1 for g,v in Counter(z).items()) for z in s)/n,
   'multiple_distinct_gallows':sum(len(set(z)&GALLOWS)>1 for z in s)/n,
   'top_last':Counter(z[-1] for z in s).most_common(5)}

def evaluate(train,test,lexicon,n,seed,evalw):
 frequencies=Counter(train);common=sorted(frequencies,key=lambda w:(-frequencies[w],w))[:n]; assert len(common)==n<=len(lexicon)
 candidates=sorted(lexicon);rng=random.Random(seed);rng.shuffle(candidates)
 enc=dict(zip(common,candidates));dec={v:k for k,v in enc.items()};assert len(dec)==n and all(not x.startswith(ESC) for x in dec)
 # Fixed rot13 escape carries unseen words without adding an end marker; not a secrecy claim.
 out=[enc[w] if w in enc else ESC+codecs.encode(w,'rot_13') for w in test]
 decoded=[codecs.decode(w[1:],'rot_13') if w.startswith(ESC) else dec[w] for w in out]
 assert decoded==test
 key={'map':dec};raw=judge.canonical(key);bits=judge.compressed_bits(raw)
 membership={}
 for name,ws in evalw.items():
  types=set(ws);membership[name]={'token_dictionary_coverage':sum(w in dec for w in ws)/len(ws),
    'type_dictionary_coverage':sum(w in dec for w in types)/len(types),
    'token_escape_syntax':sum(w.startswith(ESC) and len(w)>1 for w in ws)/len(ws),
    'type_escape_syntax':sum(w.startswith(ESC) and len(w)>1 for w in types)/len(types)}
 # Three novel words show that spaces remain required even for the escape channel.
 a='xxqxqxx';b='qqxqqxq';c=a+'m'+b # rot13(z) is m
 assert all(x not in enc for x in (a,b,c))
 ea=ESC+codecs.encode(a,'rot_13');eb=ESC+codecs.encode(b,'rot_13');ec=ESC+codecs.encode(c,'rot_13')
 assert ea+eb==ec
 return {'key_entries':n,'key_json_bytes':len(raw),'key_compressed_bits':bits,'key_bits_per_test_token':bits/len(test),
  'plaintext_test_tokens':len(test),'escaped_token_share':sum(w not in enc for w in test)/len(test),
  'exact_roundtrip':True,'ciphertext_shape':shape(out),
  'dictionary_only_shape':shape([code for w,code in zip(test,out) if w in enc]),
  'escaped_only_shape':shape([code for w,code in zip(test,out) if w not in enc]),'manuscript_membership':membership,
  'unspaced_ambiguity':{'two_plain_words':[a,b],'one_plain_word':c,'glyph_stream':ec}}

if __name__=='__main__':
 pins={e['id']:e for e in refcorpus.pins()}
 for b in BOOKS:
  with open(pins[b]['file'],'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==pins[b]['sha256']
 for k,fn,expected in [('zl','ZL3b-n.txt','bf5b6d4ac1e3a51b1847a9c388318d609020441ccd56984c901c32b09beccafc'),('it','IT2a-n.txt','7f27a8b0feed8f6de0a99900df6bf912dd1d295c38e5f830bac8b41c3f536fb5')]:
  with open('data/raw/'+fn,'rb') as f:assert hashlib.sha256(f.read()).hexdigest()==expected
 tr,_=corpus.split_pages('practice','zl');lexicon={w for w in words(tr) if not w.startswith(ESC)}
 ev={w:words(corpus.split_pages('practice',w)[1]) for w in ('zl','it')}
 out={'lexicon_source':'ZL public practice-training paragraph words excluding z-prefix','candidate_types':len(lexicon),
      'witness_shapes':{k:shape(v) for k,v in ev.items()},'books':{}}
 for book in BOOKS:
  ws=' '.join(refcorpus.blocks_of(book)).split();assert len(ws)>=TRAIN+TEST
  assert all(w.isascii() and w.isalpha() and w.islower() for w in ws[:TRAIN+TEST])
  out['books'][book]={}
  for n in SIZES:
   out['books'][book][str(n)]={str(seed):evaluate(ws[:TRAIN],ws[TRAIN:TRAIN+TEST],lexicon,n,seed,ev) for seed in SEEDS}
 print(json.dumps(out,indent=2))
